        },
        "expectedEvidence": [
          "실행 계획에서 병목으로 판단한 구체적인 지점",
          "해당 지점에 관해 실행 계획에서 실제로 확인한 조회 방식이나 처리 범위",
          "관찰한 내용이 조회 지연을 유발한다고 판단한 이유"
        ]
      },
      "question": "포켓마켓에서 운영 화면의 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 실행 계획에서 병목으로 판단하신 지점은 어디였어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "병목으로 판단한 지점을 쿼리의 실제 처리와 연결해 구체적으로 지목한다.",
            "실행 계획에서 확인한 조회 방식이나 처리 범위를 구체적으로 설명한다.",
            "관찰한 내용이 불필요한 처리나 조회 지연으로 이어지는 이유를 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목으로 판단한 지점은 식별하지만 실행 계획에서 확인한 내용의 구체성이 부족하다.",
            "관찰 내용과 조회 지연의 연결은 설명하지만 판단 근거가 일부 생략되어 있다."
          ]
        },
        "poor": {
          "criteria": [
            "병목으로 판단한 지점을 구체적으로 식별하지 못한다.",
            "실행 계획에서 확인한 내용 없이 개선 방법이나 속도 변화만 이야기한다.",
            "제시한 관찰 내용이 조회 지연의 원인이라는 설명이 없거나 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류를 로그로 추적해 원인을 좁히는 판단을 검증한다. 알림 중복 발송의 원인을 판단하는 데 사용한 로그의 단서와 그 해석에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 같은 알림이 두 번 발송된다는 문의를 받은 상황이다.",
          "task": "로그를 통해 중복 발송이 발생한 원인을 좁혀야 했다.",
          "action": "관련 로그에서 관찰한 실행 흐름을 설명하고, 그 흐름을 근거로 원인을 판단한 논리를 제시한다.",
          "result": "로그에서 확인한 사실과 원인 판단의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "원인을 좁히는 데 사용한 구체적인 로그 단서",
          "관련 로그의 시간 관계나 실행 흐름에서 확인한 사실",
          "확인한 사실이 중복 발송의 원인을 가리킨다고 판단한 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 로그에서 무엇을 보고 원인을 좁히셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "원인 추적에 사용한 로그 단서를 구체적으로 제시한다.",
            "로그의 시간 관계나 실행 흐름에서 실제로 확인한 사실을 명확하게 설명한다.",
            "확인한 사실이 중복 발송의 원인을 가리키는 이유를 논리적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "원인 추적에 사용한 로그 단서는 제시하지만 시간 관계나 실행 흐름의 설명이 불분명하다.",
            "로그에서 확인한 사실과 원인 판단의 연결은 드러나지만 구체적인 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "구체적인 로그 단서 없이 원인에 대한 결론만 제시한다.",
            "로그에서 확인한 시간 관계나 실행 흐름을 설명하지 못한다.",
            "로그의 관찰 사실과 중복 발송 원인을 연결하는 설명이 없거나 타당하지 않다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청의 목적을 해석해 요구사항 문서의 구현 범위를 구체화할 수 있는지 확인한다. 세탁소 인터뷰 내용을 근거로 문서에 포함할 범위를 정한 판단에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰 내용을 요구사항 정의서로 정리한 상황",
          "task": "수집한 요청의 목적에 맞춰 요구사항 문서에 담을 구현 범위를 정하는 일",
          "action": "인터뷰에서 확인한 요청의 목적과 필요성을 근거로 구현 범위의 경계를 정한 판단을 설명한다.",
          "result": "문서에 담은 구현 범위와 그 범위를 정한 근거의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "요구사항 정의서에 담을 구현 범위를 정한 구체적인 근거",
          "그 근거가 된 세탁소 인터뷰의 요청 내용과 목적",
          "요청의 목적이 구현 범위의 포함 또는 제외 판단으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳 인터뷰로 요구사항 정의서를 작성하셨던데요, 문서에 담을 구현 범위는 무엇을 근거로 정하셨어요?",
      "answerTip": "당시 상황을 짧게 짚고 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "문서에 담을 구현 범위를 정한 근거를 구체적으로 설명한다.",
            "인터뷰에서 나온 실제 요청과 그 요청의 목적을 명확히 제시한다.",
            "요청의 목적에 따라 무엇을 범위에 포함하거나 제외했는지 논리적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 근거는 제시하지만 판단의 구체성이 부족하다.",
            "인터뷰 요청은 언급하지만 요청의 목적에 대한 설명이 제한적이다.",
            "요청과 범위 판단의 연결은 확인되지만 포함 또는 제외의 경계가 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위를 정한 근거 없이 문서 작성 사실만 설명한다.",
            "범위 판단의 바탕이 된 인터뷰 요청이나 목적이 드러나지 않는다.",
            "요청 내용이 구현 범위 결정으로 이어진 연결을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 흐름으로 구체화할 수 있는지 확인한다. 직접 작성한 화면설계서에서 예외 상황 하나의 처리 흐름을 설계한 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예외 상황을 포함한 화면설계서 28장을 작성한 상황",
          "task": "예외 상황 하나를 화면의 동작과 상태 변화로 구체화하는 일",
          "action": "예외가 발생하는 조건과 그에 따른 화면 반응, 이어지는 화면 상태를 하나의 처리 흐름으로 설명한다.",
          "result": "선택한 예외 상황의 화면 처리 흐름이 구현 내용을 이해할 수 있는 수준으로 드러난다."
        },
        "expectedEvidence": [
          "직접 설계한 예외 상황 하나의 구체적인 화면 처리 흐름",
          "해당 예외가 발생하는 조건과 출발 화면 상태",
          "예외에 따른 화면 반응과 이어지는 상태 또는 화면의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 예외 상황 하나는 화면에서 어떤 처리 흐름으로 설계하셨어요?",
      "answerTip": "기억나는 한 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "직접 설계한 예외 상황 하나의 처리 흐름을 구체적으로 설명한다.",
            "예외 발생 조건과 출발 화면 상태가 명확하다.",
            "화면의 반응부터 이어지는 상태 또는 화면까지 일관되게 연결해 구현할 동작을 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황과 처리 흐름은 제시하지만 일부 동작이 추상적이다.",
            "예외 발생 조건이나 출발 화면 상태의 설명이 부분적이다.",
            "화면 반응과 이후 상태의 연결은 확인되지만 일부가 불명확하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 다뤘다는 설명만 있고 실제 처리 흐름이 드러나지 않는다.",
            "어떤 조건이나 화면 상태에서 예외가 발생하는지 설명하지 못한다.",
            "예외에 따른 화면 반응과 이어지는 상태의 연결을 파악하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
